28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
68	    private Set<Pet> pets;
69	
70	    /**
71	     * Resolve the registration date at creation time: default it to the server's
72	     * current date when none was supplied, and roll a weekend date forward to the
73	     * next business day so every value derived from it (such as the membership
74	     * number's year segment) uses the adjusted date.
75	     */
76	    @PrePersist
77	    private void resolveRegistrationDate() {
78	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
79	    }
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    /**
98	     * The owner's locality: the canonical region derived from its {@link #city}
99	     * via the fixed {@link CityRegion} table, or {@code "UNKNOWN"} when the city
100	     * is not in the table.
101	     */
102	    public String getLocality() {
103	        return CityRegion.regionFor(this.city);
104	    }
105	
106	    public String getTelephone() {
107	        return this.telephone;
108	    }
109	
110	    public void setTelephone(String telephone) {
111	        this.telephone = telephone;
112	    }
113	
114	    public String getEmail() {
115	        return this.email;
116	    }
117	
118	    public void setEmail(String email) {
119	        this.email = email;
120	    }
121	
122	    public LocalDate getRegistrationDate() {
123	        return this.registrationDate;
124	    }
125	
126	    public void setRegistrationDate(LocalDate registrationDate) {
127	        this.registrationDate = registrationDate;
128	    }
129	
130	    public String getCustomerCode() {
131	        return this.customerCode;
132	    }
133	
134	    public void setCustomerCode(String customerCode) {
135	        this.customerCode = customerCode;
136	    }
137	
138	    /**
139	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
140	     * where {@code YY} is the last two digits of the {@link #registrationDate}
141	     * year (e.g. {@code "LON-SMI-0007-M26"}). Derived from the owner's own fields.
142	     */
143	    public String getMembershipNumber() {
144	        if (this.customerCode == null || this.registrationDate == null) {
145	            return null;
146	        }
147	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
148	    }
149	
150	    public String getHouseholdId() {
151	        return this.householdId;
152	    }
153	
154	    public void setHouseholdId(String householdId) {
155	        this.householdId = householdId;
156	    }
157	
158	    /**
159	     * The owner's membership tier, derived from the owner's own fields. Returns
160	     * {@code "SILVER"} when the owner has no namesakes and a contact email on
161	     * file, and {@code "BRONZE"} otherwise.
162	     */
163	    public String getMembershipTier() {
164	        boolean hasEmail = this.email != null && !this.email.isEmpty();
165	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
166	        return (noNamesakes && hasEmail) ? "SILVER" : "BRONZE";
167	    }
168	
169	    public Integer getNamesakeCount() {
170	        return this.namesakeCount;
171	    }
172	
173	    public void setNamesakeCount(Integer namesakeCount) {
174	        this.namesakeCount = namesakeCount;
175	    }
176	
177	    protected Set<Pet> getPetsInternal() {
178	        if (this.pets == null) {
179	            this.pets = new HashSet<>();
180	        }
181	        return this.pets;
182	    }
183	
184	    protected void setPetsInternal(Set<Pet> pets) {
185	        this.pets = pets;
186	    }
187	
188	    public List<Pet> getPets() {
189	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
190	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
191	        return Collections.unmodifiableList(sortedPets);
192	    }
193	
194	    public void setPets(List<Pet> pets) {
195	        this.pets = new HashSet<>(pets);
196	    }
197	
198	    public void addPet(Pet pet) {
199	        getPetsInternal().add(pet);
200	        pet.setOwner(this);
201	    }
202	
203	    /**
204	     * Return the Pet with the given name, or null if none found for this Owner.
205	     *
206	     * @param name to test
207	     * @return true if pet name is already in use
208	     */
209	    public Pet getPet(String name) {
210	        return getPet(name, false);
211	    }
212	
213	    /**
214	     * Return the Pet with the given name, or null if none found for this Owner.
215	     *
216	     * @param name to test
217	     * @return true if pet name is already in use
218	     */
219	    public Pet getPet(String name, boolean ignoreNew) {
220	        name = name.toLowerCase();
221	        for (Pet pet : getPetsInternal()) {
222	            if (!ignoreNew || !pet.isNew()) {
223	                String compName = pet.getName();
224	                compName = compName.toLowerCase();
225	                if (compName.equals(name)) {
226	                    return pet;
227	                }
228	            }
229	        }
230	        return null;
231	    }
232	
233	    public Pet getPet(Integer petId) {
234	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
235	    }
236	
237	    @Override
238	    public String toString() {
239	        return new ToStringCreator(this)
240	
241	            .append("id", this.getId())
242	            .append("new", this.isNew())
243	            .append("lastName", this.getLastName())
244	            .append("firstName", this.getFirstName())
245	            .append("address", this.address)
246	            .append("city", this.city)
247	            .append("telephone", this.telephone)
248	            .append("email", this.email)
249	            .toString();
250	    }
251	}
