20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Produces the customer code assigned to a new {@link Owner}.
24	 *
25	 * <p>The code is formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3}
26	 * and {@code LAST3} are the upper-cased first three letters of the owner's city
27	 * and last name, and {@code NNNN} is a 4-digit zero-padded per-city sequence
28	 * equal to one more than the number of owners already in that city (e.g.
29	 * {@code 'LON-SMI-0007'}).
30	 */
31	@Component
32	public class CustomerCodeGenerator {
33	
34	    private static final int PREFIX_LENGTH = 3;
35	
36	    private final OwnerRepository ownerRepository;
37	
38	    public CustomerCodeGenerator(OwnerRepository ownerRepository) {
39	        this.ownerRepository = ownerRepository;
40	    }
41	
42	    /**
43	     * Generate the customer code for the given owner based on its city, last
44	     * name and the current number of owners in that city.
45	     *
46	     * @param owner the owner being registered
